import base64
import json
import os
from typing import Any, Dict, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _to_base64_document(document: Any) -> Optional[str]:
    if document is None:
        return None
    if isinstance(document, (bytes, bytearray)):
        return base64.b64encode(document).decode("utf-8")
    if isinstance(document, str):
        if os.path.exists(document):
            with open(document, "rb") as f:
                return base64.b64encode(f.read()).decode("utf-8")
        return document
    if hasattr(document, "read"):
        content = document.read()
        if isinstance(content, str):
            content = content.encode("utf-8")
        return base64.b64encode(content).decode("utf-8")
    return None


def _normalize_money(value: Any) -> Dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, dict):
        return {
            k: value.get(k)
            for k in ("amount", "currency", "amount_value", "amountText", "currencyCode")
            if value.get(k) is not None
        }
    return {"value": value}


def _normalize_vendor(address: Any) -> Dict[str, Any]:
    if address is None:
        return {}
    if isinstance(address, dict):
        return {k: v for k, v in address.items() if v not in (None, "", [], {})}
    return {"raw": address}


def _parse_invoice_result(result: Any) -> Dict[str, Any]:
    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = doc.fields if doc and getattr(doc, "fields", None) else {}

    def field_value(name: str) -> Any:
        f = fields.get(name)
        if f is None:
            return None
        for attr in ("value", "content", "value_string", "value_number", "value_date", "value_currency"):
            if hasattr(f, attr):
                v = getattr(f, attr)
                if v is not None:
                    return v
        return getattr(f, "content", None)

    vendor_name = field_value("VendorName")
    customer_name = field_value("CustomerName")
    invoice_id = field_value("InvoiceId")
    purchase_order = field_value("PurchaseOrder")
    invoice_date = field_value("InvoiceDate")
    due_date = field_value("DueDate")

    invoice_total = field_value("InvoiceTotal")
    subtotal = field_value("SubTotal")
    total_tax = field_value("TotalTax")

    billing_address = field_value("BillingAddress")
    shipping_address = field_value("ShippingAddress")
    vendor_address = field_value("VendorAddress")

    items = []
    for item in (field_value("Items") or []):
        item_fields = getattr(item, "value_array", None) or getattr(item, "valueObject", None) or []
        line = {}
        if isinstance(item, dict):
            line = item
        elif hasattr(item, "value_object") and item.value_object:
            obj = item.value_object
            for key in ("Description", "Quantity", "UnitPrice", "ProductCode", "Tax", "Amount", "Date"):
                if key in obj:
                    val = obj[key]
                    line[key[0].lower() + key[1:]] = getattr(val, "content", None) if hasattr(val, "content") else val
        elif item_fields:
            line = {"raw": str(item_fields)}
        items.append(line)

    normalized = {
        "vendor_name": vendor_name,
        "customer_name": customer_name,
        "invoice_id": invoice_id,
        "purchase_order": purchase_order,
        "invoice_date": invoice_date,
        "due_date": due_date,
        "subtotal": _normalize_money(subtotal),
        "total_tax": _normalize_money(total_tax),
        "invoice_total": _normalize_money(invoice_total),
        "billing_address": _normalize_vendor(billing_address),
        "shipping_address": _normalize_vendor(shipping_address),
        "vendor_address": _normalize_vendor(vendor_address),
        "items": items,
    }

    return {k: v for k, v in normalized.items() if v not in (None, "", [], {}, [])}


def extract_expense_fields(document: Any, *, endpoint: Optional[str] = None, key: Optional[str] = None) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using
    Azure Document Intelligence prebuilt invoice.
    """
    endpoint = endpoint or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY are required")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    doc_b64 = _to_base64_document(document)
    if doc_b64 is None:
        raise ValueError("Unsupported document input")

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=base64.b64decode(doc_b64) if isinstance(document, (bytes, bytearray)) else document,
    )
    result = poller.result()

    normalized = _parse_invoice_result(result)
    return json.loads(json.dumps(normalized, default=str))
